import{_ as i,o as e,c as s,a2 as t}from"./chunks/framework.CqGPl1zp.js";const r="/newx-doc/assets/Stability-%E5%88%9B%E5%BB%BA%E5%AF%86%E9%92%A5.C-nzr9xL.png",l="/newx-doc/assets/Stable-Diffusion-%E5%AE%98%E6%96%B9.DlU5e5E_.png",g=JSON.parse('{"title":"【模型接入】Stable Diffusion","description":"","frontmatter":{},"headers":[],"relativePath":"ai/stable-diffusion.md","filePath":"ai/stable-diffusion.md","lastUpdated":null}'),p={name:"ai/stable-diffusion.md"};function n(o,a,h,d,c,b){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="【模型接入】stable-diffusion" tabindex="-1">【模型接入】Stable Diffusion <a class="header-anchor" href="#【模型接入】stable-diffusion" aria-label="Permalink to &quot;【模型接入】Stable Diffusion&quot;">​</a></h1><p>项目基于 Spring AI 提供的 <a href="https://github.com/spring-projects/spring-ai/tree/main/models/spring-ai-stability-ai" target="_blank" rel="noreferrer"><code>spring-ai-stability-ai</code></a> ，实现 Stable Diffusion 的接入，提供 AI 作图的功能。</p><p>对应的 Spring AI 客户端为 <a href="https://docs.spring.io/spring-ai/reference/api/image/stabilityai-image.html" target="_blank" rel="noreferrer">StabilityAiImageClient</a> 。</p><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>由于 <a href="https://github.com/CompVis/stable-diffusion" target="_blank" rel="noreferrer">Stable Diffusion</a> 是开源模型，所以可以私有化部署。</p><p>而它的开源它的公司 Stability AI，提供了对应的云服务，可以直接使用。</p><p>下面，我们来看看这两种方式怎么申请（部署）？</p><p>友情提示：一般情况下，如果是为了体验 AI 作图，建议直接采用“方式一：申请 Stability 密钥”，更加简单方便！</p><h3 id="_1-1-方式一-申请-stability-密钥" tabindex="-1">1.1 方式一：申请 Stability 密钥 <a class="header-anchor" href="#_1-1-方式一-申请-stability-密钥" aria-label="Permalink to &quot;1.1 方式一：申请 Stability 密钥&quot;">​</a></h3><p>① 访问 <a href="https://stability.ai/" target="_blank" rel="noreferrer">Stability AI</a> ，注册账号。</p><p>② 访问 <a href="https://platform.stability.ai/account/keys" target="_blank" rel="noreferrer">API Keys</a> ，获得一个 API Key。</p><p><img src="'+r+'" alt="创建密钥"></p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+l+`" alt="官方的密钥配置"></p><p>ps：默认官方赠送了 25 Credits，够生成几百张图。如果用完的情况下，要么再申请一个账号，要么参考 <a href="https://juejin.cn/post/7361762150010945570" target="_blank" rel="noreferrer">《Stable Diffusion 3 会员 API 充值教学》</a> 充值。</p><h3 id="_1-2-方式二-私有化部署" tabindex="-1">1.2 方式二：私有化部署 <a class="header-anchor" href="#_1-2-方式二-私有化部署" aria-label="Permalink to &quot;1.2 方式二：私有化部署&quot;">​</a></h3><p>友情提示：虽然 Stable Diffusion 可以私有化部署，但是 Spring AI 没兼容私有化部署后的 HTTP API！</p><p>这样就导致，即使私有化部署，项目还是无法对接使用！等后续我们看看，怎么可以兼容一下！！！</p><p>① 方式一：参考 <a href="https://github.com/AbdBarho/stable-diffusion-webui-docker/wiki/Setup" target="_blank" rel="noreferrer">https://github.com/AbdBarho/stable-diffusion-webui-docker/wiki/Setup</a> 文档，使用 Docker 部署。不过要注意，如果你是 MacOS + 苹果芯片，不支持！</p><p>② 方式二：参考 <a href="https://devwl.com/posts/stable-diffusion-webui/" target="_blank" rel="noreferrer">https://devwl.com/posts/stable-diffusion-webui/</a> 文档，直接本机部署。我是 MacOS + 苹果芯片，已经跑通！如果你要开启 API 功能，启动命令得是</p><div class="language-Bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./webui.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api</span></span></code></pre></div><p>这样，你在 <a href="http://127.0.0.1:7860/docs" target="_blank" rel="noreferrer">http://127.0.0.1:7860/docs</a> 地址，就可以看到 <code>/sdapi/v1/txt2img</code> 文字生成图片 API。不过正如我前面所说的，Spring AI 没兼容该接口！！！</p><p>③ 方式三：参考 <a href="https://www.cnblogs.com/Serverless/p/18101931" target="_blank" rel="noreferrer">https://www.cnblogs.com/Serverless/p/18101931</a> 文档，使用 Serverless 部署。不过我没试过，只是提供个资料哈~</p><h2 id="_2-ai-绘图" tabindex="-1">2. AI 绘图 <a class="header-anchor" href="#_2-ai-绘图" aria-label="Permalink to &quot;2. AI 绘图&quot;">​</a></h2><p>使用 <a href="./image">《AI 绘图》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的图像模型。</p><p>模型有：<code>stable-diffusion-v1-6</code> 等等。</p><p>TODO @AI：这里的模型，需要更新下么？</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 OpenAiImageClient 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>spring.ai.stabilityai</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    stabilityai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-e53UqbboF8QJCscYvzJscJxJXoFcFg4iJjl1oqgE7baJETmx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 你的密钥</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getImageModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，StabilityAiImageModelTests 里有对应的测试用例，可以参考。</p>`,35)])])}const k=i(p,[["render",n]]);export{g as __pageData,k as default};
